INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M28-CE001', 'HDSAT-RW-M28-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A cognitive bias is a systematic pattern of deviation from the norm or rationality in judgment. Individuals create their own "subjective reality" from their perception of the input. An individual''s construction of reality, not the objective input, may dictate their behavior in the world. Thus, cognitive biases may sometimes lead to perceptual distortion, inaccurate judgment, illogical interpretation, and irrationality. While cognitive biases may initially appear to be negative, some are adaptive. They may lead to more effective actions in a given context. Furthermore, allowing cognitive biases enables faster decisions which can be desirable when timeliness is more valuable than accuracy, as illustrated in heuristics. Other cognitive biases are a "by-product" of human processing limitations, resulting from a lack of appropriate mental mechanisms (bounded rationality), the impact of an individual''s constitution and biological state (embodied cognition), or simply from a limited capacity for information processing. Cognitive biases can make individuals more inclined to endorsing pseudoscientific beliefs by requiring less evidence for claims that confirm their preconceptions. This can potentially distort their perceptions and lead to inaccurate judgments. A continually evolving list of cognitive biases has been identified over the last six decades of research on human judgment and decision-making in cognitive science, social psychology, and behavioral economics.', 'Which quotation from the text most directly supports the claim that biases are not always harmful?', '[{"id": "A", "text": "An individual''s construction of reality, not the objective input, may dictate their behavior in the world."}, {"id": "B", "text": "Cognitive biases can make individuals more inclined to endorsing pseudoscientific beliefs."}, {"id": "C", "text": "While cognitive biases may initially appear to be negative, some are adaptive."}, {"id": "D", "text": "A cognitive bias is a systematic pattern of deviation from the norm or rationality in judgment."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Cognitive bias", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Cognitive_bias', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M28-CE001', 'C', ARRAY['C']::TEXT[], 'The correct quotation explicitly calls some biases adaptive.', '{"D": "This sentence defines cognitive bias.", "A": "This sentence describes subjective reality.", "B": "This sentence describes a harmful effect."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M28-CI002', 'HDSAT-RW-M28-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Classical conditioning (also respondent conditioning and Pavlovian conditioning) is a behavioral procedure in which a biologically potent stimulus (e.g. food, a puff of air on the eye) is paired with a neutral stimulus (e.g. the sound of a musical triangle). The term classical conditioning refers to the process of an automatic, conditioned response that is paired with a specific stimulus. It is essentially equivalent to a signal. Ivan Pavlov, the Russian physiologist, studied classical conditioning with detailed experiments with dogs, and published the experimental results in 1897. In the study of digestion, Pavlov observed that the experimental dogs salivated when fed red meat. Pavlovian conditioning is distinct from operant conditioning (instrumental conditioning), through which the strength of a voluntary behavior is modified, either by reinforcement or by punishment. However, classical conditioning can affect operant conditioning; classically conditioned stimuli can reinforce operant responses. Classical conditioning is a basic behavioral mechanism, and its neural substrates are now beginning to be understood. Though it is sometimes hard to distinguish classical conditioning from other forms of associative learning (e.g., instrumental learning and human associative memory); a number of observations differentiate them, especially the contingencies whereby learning occurs.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Classical conditioning involves no pairing of stimuli."}, {"id": "B", "text": "Classical conditioning was discovered by B. F. Skinner."}, {"id": "C", "text": "Classical conditioning modifies voluntary behavior through punishment."}, {"id": "D", "text": "Classical conditioning pairs a neutral stimulus with a potent one to produce an automatic conditioned response."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Classical conditioning", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Classical_conditioning', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M28-CI002', 'D', ARRAY['D']::TEXT[], 'The passage defines classical conditioning, describes Pavlov''s work, and contrasts it with operant conditioning.', '{"C": "The text describes pairing a biologically potent stimulus with a neutral one.", "B": "The text says operant conditioning modifies voluntary behavior.", "A": "The text credits Ivan Pavlov with the experiments."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M28-INF002', 'HDSAT-RW-M28-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Classical conditioning (also respondent conditioning and Pavlovian conditioning) is a behavioral procedure in which a biologically potent stimulus (e.g. food, a puff of air on the eye) is paired with a neutral stimulus (e.g. the sound of a musical triangle). The term classical conditioning refers to the process of an automatic, conditioned response that is paired with a specific stimulus. It is essentially equivalent to a signal. Ivan Pavlov, the Russian physiologist, studied classical conditioning with detailed experiments with dogs, and published the experimental results in 1897. In the study of digestion, Pavlov observed that the experimental dogs salivated when fed red meat. Pavlovian conditioning is distinct from operant conditioning (instrumental conditioning), through which the strength of a voluntary behavior is modified, either by reinforcement or by punishment. However, classical conditioning can affect operant conditioning; classically conditioned stimuli can reinforce operant responses. Classical conditioning is a basic behavioral mechanism, and its neural substrates are now beginning to be understood. Though it is sometimes hard to distinguish classical conditioning from other forms of associative learning (e.g., instrumental learning and human associative memory); a number of observations differentiate them, especially the contingencies whereby learning occurs.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M28-INF002', 'A', ARRAY['A']::TEXT[], 'A conditioned stimulus reinforcing an operant response shows the two processes can work together.', '{"B": "The text says classical conditioning can affect operant conditioning.", "D": "That contradicts the stated interaction.", "C": "The text describes both as forms of learning in the same organisms."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
