INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M28-CE008', 'HDSAT-RW-M28-CE008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Attachment theory is a psychological and evolutionary framework concerning the relationships between humans, particularly the importance of early bonds between infants and their primary caregivers. Developed by psychiatrist and psychoanalyst John Bowlby (1907–90), the theory posits that infants need to form a close relationship with at least one primary caregiver to ensure their survival, and to develop healthy social and emotional functioning. Pivotal aspects of attachment theory include the observation that infants seek proximity to attachment figures, especially during stressful situations. Secure attachments are formed when caregivers are sensitive and responsive in social interactions, and consistently present, particularly between the ages of six months and two years. As children grow, they use these attachment figures as a secure base from which to explore the world and return to for comfort. The interactions with caregivers form patterns of attachment, which in turn create internal working models that influence future relationships. Separation anxiety or grief following the loss of an attachment figure is considered to be a normal and adaptive response for an attached infant.', 'Which quotation from the text most directly supports the claim that early attachment shapes later relationships?', '[{"id": "A", "text": "Separation anxiety or grief following the loss of an attachment figure is considered to be a normal and adaptive response."}, {"id": "B", "text": "The interactions with caregivers form patterns of attachment, which in turn create internal working models that influence future relationships."}, {"id": "C", "text": "Attachment theory is a psychological and evolutionary framework concerning the relationships between humans."}, {"id": "D", "text": "Infants seek proximity to attachment figures, especially during stressful situations."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Attachment theory", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Attachment_theory', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M28-CE008', 'B', ARRAY['B']::TEXT[], 'The correct quotation explicitly links early patterns to future relationships.', '{"C": "This sentence defines the theory''s scope.", "D": "This sentence describes proximity seeking.", "A": "This sentence describes separation responses."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M28-CI009', 'HDSAT-RW-M28-CI009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Attention is the concentration of awareness directed at some task or phenomenon while mostly excluding others. Across disciplines, the nature of this directedness is conceptualized in different ways. In cognitive psychology, attention is often described as the allocation of limited cognitive processing resources to a subset of information, thoughts, or tasks. In neuropsychology, attention is understood as a set of mechanisms by which sensory cues and internal goals modulate neuronal tuning and orient behavioral and cognitive processes. Attention is not a unitary phenomenon but an umbrella term for multiple related processes, including selective attention (prioritizing some stimuli over others), sustained attention (maintaining focus), divided attention (sharing resources across tasks), and orienting (shifting focus in space or time). These processes are supported by distributed neural networks in frontal, parietal, and subcortical regions and are closely linked to working memory, executive functions, and consciousness. Patterns of attention also vary across cultures, especially in how individuals attend to context versus focal objects and how children are guided to manage attention in everyday activities. == History == === 16th century === John B. Watson called Juan Luis Vives the father of modern psychology. In his book De Anima et Vita, Vives argued that the more closely one attends to stimuli, the better they are retained in memory. === 17th century === Daniel E.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Attention is unrelated to working memory."}, {"id": "B", "text": "Attention is a single, simple process."}, {"id": "C", "text": "Attention involves no selection of information."}, {"id": "D", "text": "Attention is the selective concentration of awareness, comprising several processes supported by distributed brain networks."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Attention", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Attention', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
